'use client'

import type { User } from '@supabase/supabase-js'

export default function Feed({ user }: { user: User }) {
  const displayName =
    user.user_metadata?.nickname || user.email?.split('@')[0] || 'User'

  return (
    <div className="flex flex-col h-full">
      {/* Feed Header */}
      <div className="p-4 border-b sticky top-0 bg-white z-10">
        <h2 className="text-lg font-semibold text-gray-800">Feed</h2>
        <p className="text-sm text-gray-500">Welcome, {displayName}</p>
      </div>

      {/* Feed Content */}
      <div className="flex-1 p-4 space-y-4">
        {/* Example feed items (you can replace these later) */}
        <div className="bg-gray-50 rounded-xl p-4 border">
          <p className="font-medium text-sm text-gray-800">System</p>
          <p className="text-sm text-gray-600 mt-1">
            Welcome to the room! This is the feed area.
          </p>
          <p className="text-xs text-gray-400 mt-2">Just now</p>
        </div>

        <div className="bg-gray-50 rounded-xl p-4 border">
          <p className="font-medium text-sm text-gray-800">Announcement</p>
          <p className="text-sm text-gray-600 mt-1">
            You can later put posts, music, or room activity here.
          </p>
          <p className="text-xs text-gray-400 mt-2">2 min ago</p>
        </div>

        <div className="bg-gray-50 rounded-xl p-4 border">
          <p className="font-medium text-sm text-gray-800">Tip</p>
          <p className="text-sm text-gray-600 mt-1">
            The chat is now floating on the right side.
          </p>
          <p className="text-xs text-gray-400 mt-2">5 min ago</p>
        </div>
      </div>
    </div>
  )
}